L[ [=[%s finds gathering nodes by sliding the minimap under your cursor. While it scans, the map and what is on it (quest areas, icons) can flash or vanish for a moment.

That comes from the addon itself, not FlareUI, and happens on Blizzard's minimap too. NodeRadar, FarmMap and GatherMemory find nodes without moving the map.]=] ] = "%s trouve les gisements de récolte en faisant glisser la minicarte sous votre curseur. Pendant l'analyse, la carte et ce qu'elle affiche (zones de quête, icônes) peuvent clignoter ou disparaître un instant. Cela vient de l'addon lui-même, pas de FlareUI, et se produit aussi sur la minicarte de Blizzard. NodeRadar, FarmMap et GatherMemory trouvent les gisements sans déplacer la carte."
L["%s holds %s. Put the radial there instead?"] = "%s contient %s. Y placer le radial à la place ?"
