L[ [=[* In it: every FlareUI setting, and where FlareUI's frames sit on any Edit Mode layout
* Not in it: Blizzard's bars and frames, which come with your Edit Mode layout
* Switching profiles offers the layout the profile was set up on. From another character, copy it with Copy Layout Code (About) or Sync Blizz UI (Settings).]=] ] = [=[* Dedans : tous les réglages de FlareUI, et l'emplacement des cadres de FlareUI sur n'importe quelle disposition du Mode Édition
* Pas dedans : les barres et cadres de Blizzard, qui suivent votre disposition du Mode Édition
* Changer de profil propose la disposition sur laquelle le profil a été créé. Depuis un autre personnage, copiez-la avec Copier le code de disposition (À propos) ou Sync Blizz UI (Paramètres).]=]
L[ [=[* New: a copy of the profile in use, or FlareUI's defaults
* Rename: a new name for the profile in use
* Delete: removes a profile you aren't using]=] ] = [=[* Nouveau : une copie du profil utilisé, ou les paramètres par défaut de FlareUI
* Renommer : un nouveau nom pour le profil utilisé
* Supprimer : retire un profil que vous n'utilisez pas]=]
L[ [=[* New: FlareUI's defaults
* Duplicate: a copy of the profile in use
* Delete: removes a profile you aren't using]=] ] = [=[* Nouveau : les paramètres par défaut de FlareUI
* Dupliquer : une copie du profil utilisé
* Supprimer : retire un profil que vous n'utilisez pas]=]
L[ [=[* New: FlareUI's defaults
* Rename: a new name for the profile in use
* Duplicate: a copy of the profile in use
* Delete: removes a profile you aren't using]=] ] = [=[* Nouveau : les réglages par défaut de FlareUI
