L["A button beside the bags' cleanup button opens a drawer: Quest Items, Equipment, Materials or Consumables. Everything else dims."] = "Un bouton à côté du bouton de nettoyage des sacs ouvre un tiroir : Objets de quête, Équipement, Matériaux ou Consommables. Tout le reste s'assombrit."
L[ [=[A button for the game's master volume:
