L["A button for you and each party member: aim at a person to cast on them."] = "Un bouton pour vous et chaque membre du groupe : visez une personne pour lui lancer le sort."
L["A button in the meter's header that starts a 10-second pull countdown; right-click it to cancel. It shows only while you are in a group."] = "Bouton dans l'en-tête du compteur qui lance un pull de 10 s ; clic droit pour annuler. Visible uniquement en groupe."
L["A button in the meter's header that starts a ready check. It shows only when you lead or assist a group."] = "Bouton dans l'en-tête du compteur qui lance un appel. Visible si vous êtes chef ou assistant."
L["A camera that zooms out further"] = "Une caméra qui dézoome plus loin"
L["A cast bar under each member."] = "Une barre d'incantation sous chaque membre."
L["A character shows up once you've logged in on it."] = "Un personnage apparaît une fois que vous vous y êtes connecté."
L["A clash means two radials share a key. The first in the list wins."] = "Un conflit signifie que deux radiaux partagent une touche. Le premier de la liste l'emporte."
L["A clash means two radials with the same reach share a key. The first in the list wins."] = "Un conflit signifie que deux radiaux de même portée partagent une touche. Le premier de la liste l'emporte."
L["A cleaner chat frame with a customisable header."] = "Un chat plus épuré avec un en-tête personnalisable."
L["A click on a tab always wins until the next change."] = "Un clic sur un onglet l'emporte toujours jusqu'au prochain changement."
L["A dark outline around the letters."] = "Un contour sombre autour des lettres."
L["A dispellable debuff colours the frame's border in its type's colour."] = "Un débuff dissipable colore la bordure du cadre selon son type."
L["A dispellable debuff outlines the health bar in its type's colour."] = "Un débuff dispellable entoure la barre de vie de la couleur de son type."
L["A dot before each quest. Click it to focus the quest on the map."] = "Un point avant chaque quête. Cliquez dessus pour afficher la quête sur la carte."
L["A dot before each quest: click it to focus the quest on the map."] = "Un point avant chaque quête : cliquez dessus pour afficher la quête sur la carte."
L[ [=[A drop shadow under the letters.
* Soft: 1 pixel away
* Strong: 2 pixels away]=] ] = [=[Une ombre portée sous les lettres.
* Légère : à 1 pixel
* Forte : à 2 pixels]=]
