u2022 Soft: 1 pixel away
u2022 Strong: 2 pixels away]=] ] = "Plus utilisée, buggée"
L[ [=[A gold edge and a light on the active button:
* Your stance or form
* A queued Heroic Strike, Cleave, Maul or Raptor Strike (it pulses)
* Auto Shot and wands while they repeat]=] ] = [=[Un bord doré et une lueur sur le bouton actif :
* Votre posture ou forme
