L["A gold glow round a buff that is missing."] = "Une lueur dorée autour d'un buff manquant."
L["A gold glow round a missing buff."] = "Une lueur dorée autour d'un buff manquant."
L["A green \">\" before whispers you get and a red \"<\" before ones you send, instead of \"whispers:\" and \"To\"."] = "Un « > » vert avant les chuchotements reçus et un « < » rouge avant ceux que vous envoyez, au lieu de « chuchote : » et « À »."
L["A green arrow marks gear that beats what you wear."] = "Une flèche verte signale l'équipement meilleur que celui que vous portez."
L["A group buff only shows when no one else of your class is in the group to give it."] = "Un buff de groupe ne s'affiche que si aucun autre joueur de votre classe n'est dans le groupe pour le donner."
L["A header with your tabs and buttons"] = "Un en-tête avec vos onglets et boutons"
L["A key set this way wins over any other radial on the same key."] = "Une touche définie ainsi l'emporte sur tout autre radial sur la même touche."
L["A key that minimizes or opens the tracker."] = "Une touche qui réduit ou rouvre le suivi."
L["A key that shrinks the tracker to its header, or opens it again."] = "Une touche qui réduit le suivi à son en-tête, ou le rouvre."
L["A key that switches between damage and threat."] = "Une touche qui bascule entre dégâts et menace."
L["A key that switches the meter between damage and threat."] = "Une touche qui bascule le compteur entre dégâts et menace."
L["A little more space between chat lines."] = "Un peu plus d'espace entre les lignes du chat."
L["A mark near the end of the bar: press your next spell after it and it goes off as soon as this one ends."] = "Un repère près de la fin de la barre : appuyez sur votre prochain sort après lui et il part dès que celui-ci se termine."
L["A Meter tab beside your chat tabs shows the meter inside the chat window."] = "Un onglet Compteur à côté de vos onglets de chat affiche le compteur dans la fenêtre de chat."
L["A Meter tab with the chat's tabs: the meter in the chat window, the chat back on its own tabs."] = "Un onglet Compteur parmi ceux du chat : le compteur dans la fenêtre de chat, le chat sur ses propres onglets."
L["A minimap with square and round styles."] = "Une minicarte en style carré ou rond."
L["A minimized tracker shrinks to a small + button instead of its header."] = "Une fois réduit, le suivi devient un petit bouton + au lieu de son en-tête."
L["A new radial starts on this character only."] = "Un nouveau radial ne concerne d'abord que ce personnage."
L["A newly learned rank replaces the lower rank on your bars."] = "Un rang nouvellement appris remplace le rang inférieur sur vos barres."
L["A newly learned rank replaces the rank below it on your bars."] = "Un rang nouvellement appris remplace le rang inférieur sur vos barres."
L["A note icon in each chat window's top right corner. Click it to copy that window's lines."] = "Une icône de note en haut à droite de chaque fenêtre de chat. Cliquez dessus pour copier les lignes de cette fenêtre."
L["A paw marks the food in your bags your hunter pet eats."] = "Une patte marque dans vos sacs la nourriture que mange votre familier de chasseur."
L["A paw marks the food your hunter pet eats."] = "Une patte marque la nourriture que mange votre familier de chasseur."
L["A quest mark on enemies you need for a quest."] = "Un symbole de quête sur les ennemis utiles à une quête."
L["A radial's Quest Items button uses your quest items from anywhere."] = "Le bouton Objets de quête d'un radial utilise vos objets de quête où que vous soyez."
L["A red line on the Threat tab's bars, where you would pull the enemy off the tank."] = "Une ligne rouge sur les barres de l'onglet Menace, à l'endroit où vous prendriez l'ennemi au tank."
L["A reload puts a button back. New addons go in the drawer."] = "Un rechargement remet un bouton en place. Les nouveaux addons vont dans le tiroir."
L["A ring of spells, items, macros and more. Hold keybind, point, release."] = "Un anneau de sorts, objets, macros et plus. Maintenez la touche, visez, relâchez."
L["A ring of spells, items, macros and more. Hold the key, point, release."] = "Un anneau de sorts, objets, macros et plus. Maintenez la touche, visez, relâchez."
L["A rough guide from stats: main stat first, then Stamina, then other ratings. Special effects aren't judged."] = "Une estimation selon les stats : la stat principale d'abord, puis l'Endurance, puis les autres caractéristiques. Les effets spéciaux ne sont pas pris en compte."
L["A rough guide from the item's stats: your main stat counts most, then Stamina, then other ratings. It can't judge special effects."] = "Une estimation à partir des stats de l'objet : votre stat principale compte le plus, puis l'Endurance, puis les autres caractéristiques. Elle ne peut pas juger les effets spéciaux."
L["A short rumble when a spell lights up on your action bars."] = "Une courte vibration quand un sort s'illumine sur vos barres d'action."
