L["A small note icon in the top right corner of each chat window. Click it to see that window's lines in a box you can copy from."] = "Une petite icône de note en haut à droite de chaque fenêtre de chat. Cliquez dessus pour afficher les lignes de cette fenêtre dans une boîte à copier."
L["A small quest mark on enemies you need for a quest."] = "Un petit symbole de quête sur les ennemis dont vous avez besoin pour une quête."
L["A sound as a reminder appears. Picking one plays it."] = "Un son quand un rappel apparaît. Choisir un son le joue."
L["A sound when a reminder appears. Picking one plays it."] = "Un son quand un rappel apparaît. Choisir un son le joue."
