L["Blizzard's Cooldown Manager in FlareUI's look: the Tracked Bars like FlareUI's cast bars, the Tracked Buffs icons like FlareUI's buffs."] = "Le gestionnaire de CD de Blizzard au style FlareUI : les Barres suivies comme les barres d'incantation de FlareUI, les icônes des Buffs suivis comme les buffs de FlareUI."
