L[ [=[How a keybind opens the radial.
* Hold: hold the key, point, release to use
* Toggle: press to open, then left-click or press again to use; right-click goes back or closes]=] ] = [=[Comment un raccourci ouvre le radial.
* Maintenir : maintenez la touche, visez, relâchez pour utiliser
* Basculer : appuyez pour ouvrir, puis clic gauche ou réappuyez pour utiliser ; clic droit pour retour ou fermer]=]
L[ [=[How a keybind opens the radial.
* Hold: hold the key, point, release to use
* Toggle: press to open, then left-click to use; press again or right-click to close (right-click goes back from a nested radial)]=] ] = [=[Comment un raccourci ouvre le radial.
* Maintenir : maintenez la touche, visez, relâchez pour utiliser
* Basculer : appuyez pour ouvrir, puis clic gauche pour utiliser ; appuyez à nouveau ou clic droit pour fermer (le clic droit revient en arrière depuis un radial imbriqué)]=]
L[ [=[How a keybind opens the radial:
* Hold: hold the key, point, release to use
* Toggle: press to open, left-click to use; press again or right-click to close (right-click goes back from a nested radial)]=] ] = [=[Comment un raccourci ouvre le radial :
* Maintenir : maintenez la touche, visez, relâchez pour utiliser
* Basculer : appuyez pour ouvrir, clic gauche pour utiliser ; appuyez à nouveau ou clic droit pour fermer (le clic droit revient en arrière depuis un radial imbriqué)]=]
L["How auras on unit frames show their time left."] = "Comment les auras des cadres d'unité affichent leur temps restant."
L[ [=[How big the whole interface is, set as you log in, for every character:
* Blizzard's: the game's own UI Scale setting
* Pixel Perfect: one interface pixel per screen pixel
* 4K, 1440p, 1080p: pixel perfect for that screen (at 125% for Windows' 125% display scaling)
* Custom: any scale, smaller or bigger than Blizzard's slider allows]=] ] = [=[La taille de toute l'interface, appliquée à la connexion, pour tous les personnages :
* Blizzard : le réglage d'échelle de l'interface du jeu
* Pixel parfait : un pixel d'interface par pixel d'écran
* 4K, 1440p, 1080p : pixel parfait pour cet écran (à 125 % pour l'échelle d'affichage à 125 % de Windows)
* Personnalisé : n'importe quelle échelle, plus petite ou plus grande que ce que permet le curseur de Blizzard]=]
L[ [=[How channels show in chat:
* Full: "[1. General - Elwynn Forest]"
* Short: "[1. General]", "[G]" for Guild, "[P]" for Party
* Number: "[1]", "[G]", "[P]"]=] ] = [=[Comment les canaux s'affichent dans le chat :
* Complet : « [1. Général - Forêt d'Elwynn] »
* Court : « [1. Général] », « [G] » pour Guilde, « [P] » pour Groupe
* Numéro : « [1] », « [G] », « [P] »]=]
