L["The art at each end of the main bar sits behind your action bars instead of over them."] = "Les décors aux deux bouts de la barre principale passent derrière vos barres d'action au lieu de les recouvrir."
L["The bank and guild bank always open your bags."] = "La banque et la banque de guilde ouvrent toujours vos sacs."
L["The bar in your class colour. Off: the classic health green."] = "Barre à la couleur de votre classe. Désactivé : vert classique."
L["The bar that switches to another set of buttons in a stance or form (Cat and Bear Form, warrior stances, Stealth...), as Blizzard's bar 1 does."] = "La barre qui change de boutons selon la posture ou la forme (Félin, Ours, postures de guerrier, Camouflage...), comme la barre 1 de Blizzard."
L["The bar that switches to its own page in Stealth, a druid form or a warrior stance."] = "La barre qui change de page en Camouflage, en forme de druide ou en posture de guerrier."
L["The bar that switches to its own page in Stealth, a druid form or a warrior stance. Any other bar, or No Auto-Paging, stays on its page."] = "La barre qui change de page en Camouflage, en forme de druide ou en posture de guerrier. Toute autre barre, ou Sans pagination auto, reste sur sa page."
L["The bar turns gold while Heroic Strike, Cleave, Maul or Raptor Strike waits for the next swing."] = "La barre devient dorée tant que Frappe héroïque, Enchaînement, Mutiler ou Attaque du raptor attend le prochain coup."
L["The bar turns grey while your target is out of the spell's range."] = "La barre devient grise quand votre cible est hors de portée du sort."
L["The bar turns red while your health is under 30%."] = "La barre devient rouge tant que votre vie est sous 30 %."
L["The bar turns red while your target is out of reach of this attack. Off, it keeps its colour."] = "La barre devient rouge tant que votre cible est hors de portée de cette attaque. Désactivé, elle garde sa couleur."
L["The bar's size."] = "La taille de la barre."
L["The bars that become the cooldown display. They can't be clicked and show only by the condition below."] = "Les barres qui deviennent l'affichage de CD. Elles ne sont pas cliquables et ne s'affichent que selon la condition ci-dessous."
L["The bars you pick become a cooldown display. They can't be clicked and show only by the conditional below."] = "Les barres choisies deviennent un affichage de CD. Elles ne sont pas cliquables et ne s'affichent que selon la condition ci-dessous."
L["The border around the chat and its edit box."] = "La bordure du chat et de sa zone de saisie."
L["The border around the meter."] = "La bordure du compteur."
L["The border around the tracker."] = "La bordure du suivi."
L["The border takes the colour of a player's class, a creature's reaction, or an item's quality."] = "La bordure prend la couleur de la classe d'un joueur, de la réaction d'une créature ou de la qualité d'un objet."
L["The bosses of an encounter, mirrored like the target frame."] = "Les boss d'une rencontre, en miroir comme le cadre de la cible."
L["The bronze ring beside FlareUI's bars."] = "L'anneau de bronze à côté des barres FlareUI."
L["The button you point at shows its action's name."] = "Le bouton visé affiche le nom de son action."
L["The button you point at shows the name of its action."] = "Le bouton visé affiche le nom de son action."
L["The button you used last is lit when the radial opens. Press the radial's button again to use it."] = "Le dernier bouton utilisé est allumé à l'ouverture du radial. Appuyez à nouveau sur le bouton du radial pour l'utiliser."
L["The button you used last is lit when the radial opens. Press the radial's controller button again to use it."] = "Le dernier bouton utilisé est allumé à l'ouverture du radial. Appuyez à nouveau sur le bouton de la manette du radial pour l'utiliser."
L["The buttons and bars you look at all day."] = "Les boutons et barres que vous regardez toute la journée."
L["The buttons in the chat header."] = "Les boutons de l'en-tête du chat."
L["The buttons in the chat header. Turn off the ones you don't use."] = "Les boutons de l'en-tête du chat. Désactivez ceux dont vous ne vous servez pas."
L["The camera holds still while the radial is open. R3 pings as usual while it is closed."] = "La caméra reste fixe quand le radial est ouvert. Fermé, R3 sert au ping comme d'habitude."
L["The camera zooms out further, and faster."] = "La caméra dézoome plus loin, et plus vite."
L["The channels and voice chat button."] = "Le bouton des canaux et du chat vocal."
L["The chat window stays up while the Meter tab is open."] = "La fenêtre de chat reste affichée tant que l'onglet Compteur est ouvert."
L["The chat's Visibility fade is ignored while the Meter tab is selected: the window stays up."] = "Le fondu de Visibilité du chat est ignoré tant que l'onglet Compteur est sélectionné : la fenêtre reste affichée."
L["The colour tones for every single FlareUI Unit Frame bar."] = "Les tons de couleur de toutes les barres des cadres d'unité FlareUI."
