L["The combo point bar along the top of the health bar (Addon Style). In FlareUI Style: Classic, Modern or Off."] = "La barre de points de combo au-dessus de la barre de vie (Style Addon). En Style FlareUI : Classique, Moderne ou Désactivé."
L["The debuffs you can dispel, up to four, two to a row in the middle of the portrait (or of the health bar without one)."] = "Les débuffs que vous pouvez dissiper, jusqu'à quatre, deux par ligne au centre du portrait (ou de la barre de vie sans portrait)."
L["The drawer opens while you point at the day/night badge and closes when you move away. Clicking still works."] = "Le tiroir s'ouvre quand vous pointez l'icône jour/nuit et se ferme quand vous vous éloignez. Le clic fonctionne toujours."
L["The drawer opens while you point at the day/night button, and closes when you move away. A click still opens and closes it."] = "Le tiroir s'ouvre tant que vous pointez le bouton jour/nuit, et se ferme quand vous vous éloignez. Un clic l'ouvre et le ferme toujours."
L["The edge the tracker is held by: Top grows it downward, Bottom upward. Automatic picks the edge nearest the screen's."] = "Le bord auquel le suivi est accroché : Haut le fait grandir vers le bas, Bas vers le haut. Automatique choisit le bord le plus proche de celui de l'écran."
L["The elixirs, Zanza, juju and Blasted Lands buffs you want kept up. Click an icon to use one from your bags."] = "Les élixirs, Zanza, juju et buffs des Terres foudroyées que vous voulez maintenir. Cliquez sur une icône pour en utiliser un de vos sacs."
L["The end art of the main bar sits behind your action bars, not over them."] = "Le décor de fin de la barre principale se place derrière vos barres d'action, et non par-dessus."
L["The end of the bar your latency covers, in red: start the next spell there and it is sent as this one lands."] = "La fin de la barre couverte par votre latence, en rouge : lancez le sort suivant à cet endroit et il est envoyé au moment où celui-ci aboutit."
L["The fight's running time in the meter's title."] = "La durée du combat dans le titre du compteur."
L["The first line: a name or an item."] = "La première ligne : un nom ou un objet."
L["The FlareUI Layout"] = "La disposition FlareUI"
L["The frame fades while the unit is out of your range. Off, it always shows in full."] = "Le cadre s'estompe tant que l'unité est hors de portée. Désactivé, il s'affiche toujours en entier."
L["The frame's size."] = "La taille du cadre."
L["The friends and Quick Join button."] = "Le bouton Amis et Rejoindre rapidement."
