L["The meter takes the chat's width and height."] = "Le compteur prend la largeur et la hauteur du chat."
L["The meter takes the size of FlareUI's chat frame, in place of the size set in Edit Mode. Needs the Chat module."] = "Le compteur prend la taille du chat FlareUI au lieu de celle du Mode Édition. Nécessite le module Chat."
