L["The pet frame fades with the player frame, on these settings. Pointing at either shows both."] = "Le cadre du familier s'estompe avec le cadre du joueur, selon ces réglages. Pointer l'un des deux affiche les deux."
L["The ping menu moves to L3."] = "Le menu de ping passe sur L3."
L["The power bar's height."] = "La hauteur de la barre de ressource."
