L["The profile |cffffff00%s|r was set up on the Edit Mode layout |cffffff00%s|r. Switch to it?"] = "Le profil |cffffff00%s|r a été créé sur la disposition du Mode Édition |cffffff00%s|r. Basculer dessus ?"
