L["The size of the icons and how many sit in a row."] = "La taille des icônes et leur nombre par ligne."
L["The size of the icons, and how many fit in a row."] = "La taille des icônes, et combien tiennent sur une ligne."
L[ [=[The size of the whole interface, for every character:
* Blizzard's: the game's own UI Scale setting
* Pixel Perfect: one interface pixel per screen pixel
* 4K, 1440p, 1080p: pixel perfect for that screen (at 125% for Windows' 125% scaling)
* Custom: any scale, beyond Blizzard's slider]=] ] = [=[La taille de toute l'interface, pour chaque personnage :
* Blizzard : le réglage d'échelle de l'interface du jeu
* Pixel parfait : un pixel d'interface par pixel d'écran
* 4K, 1440p, 1080p : pixel parfait pour cet écran (à 125 % pour une mise à l'échelle Windows de 125 %)
* Personnalisé : n'importe quelle échelle, au-delà du curseur de Blizzard]=]
L["The size of the whole radial, buttons and ring."] = "La taille du radial entier, boutons et anneau."
L["The space between a frame and its target. Widen it to clear auras on that side."] = "L'espace entre un cadre et sa cible. Élargissez-le pour dégager les auras de ce côté."
L["The stack count on each icon."] = "Le nombre de cumuls sur chaque icône."
L["The stack count on unit frame auras."] = "Le nombre de cumuls sur les auras des cadres d'unité."
L["The stack counts and cooldown numbers on your bag items. Default keeps Blizzard's font."] = "Les nombres de piles et de recharge sur les objets de vos sacs. Par défaut garde la police de Blizzard."
L["The swing's name on the left of the bar."] = "Le nom de l'attaque à gauche de la barre."
L["The switch did not go through. Use Blizzard's Settings > Gamepad > Enable Gamepad UI."] = "Le changement n'a pas abouti. Utilisez Paramètres de Blizzard > Manette > Activer l'interface manette."
L["The symbol of each debuff type you can dispel (Magic, Curse, Disease, Poison)."] = "Le symbole de chaque type de débuff que vous pouvez dissiper (Magie, Malédiction, Maladie, Poison)."
L["The symbol of each debuff type you can dispel, two to a row in the middle of the portrait (or of the health bar without one)."] = "Le symbole de chaque type de débuff que vous pouvez dissiper, deux par ligne au milieu du portrait (ou de la barre de vie s'il n'y en a pas)."
L["The tank's row on the Threat tab shows how far it is ahead of second place, like \"+25%\"."] = "La ligne du tank sur l'onglet Menace indique son avance sur le deuxième, par exemple « +25 % »."
L[ [=[The target's combo points:
* Addon Style: a bar along the top of the health bar
* FlareUI Style: Classic, Modern or Off]=] ] = [=[Les points de combo de la cible :
* Style Addon : une barre le long du haut de la barre de vie
* Style FlareUI : Classique, Moderne ou Désactivé]=]
L["The text size."] = "La taille du texte."
L["The texture of the shield (absorb) over the health bar."] = "La texture du bouclier (absorption) sur la barre de vie."
L["The texture of the shield (absorb) over the health bar. Frame Texture uses the bar's own."] = "La texture du bouclier (absorption) sur la barre de vie. Texture du cadre utilise celle de la barre."
L["The time at the right end of the bar."] = "L'heure au bout à droite de la barre."
L["The time left on a buff about to run out, at the top of its icon."] = "Le temps restant d'un buff sur le point d'expirer, en haut de son icône."
L["The time left on each icon."] = "Le temps restant sur chaque icône."
L["The time left on the right of the bar. A route you haven't flown yet counts up while it's learned."] = "Le temps restant à droite de la barre. Un trajet que vous n'avez pas encore pris compte à la hausse pendant son apprentissage."
L["The time left on unit frame auras."] = "Le temps restant sur les auras des cadres d'unité."
L["The title row: Damage Meter or Threat, the session and its timer."] = "La ligne de titre : Compteur de dégâts ou Menace, la session et sa durée."
L["The tooltips of the gear you wear show beside an item only while you hold Shift."] = "Les infobulles de l'équipement que vous portez ne s'affichent à côté d'un objet que tant que vous maintenez Maj."
L["The total also shows in the bar's text."] = "Le total s'affiche aussi dans le texte de la barre."
L["The tracker shrinks to its header there, and comes back when you leave."] = "Le suivi se réduit à son en-tête à ces endroits, et revient quand vous en partez."
L[ [=[The tracker's size:
* Width
* Max Height: how tall it grows before it scrolls
* Quest Spacing: the gap between quests]=] ] = [=[La taille du suivi :
* Largeur
* Hauteur max : jusqu'où il grandit avant de défiler
* Espacement des quêtes : l'écart entre les quêtes]=]
L["The tracker's width, and how tall it grows before it scrolls."] = "La largeur du suivi, et la hauteur qu'il atteint avant de défiler."
L["The tracker's width, how tall it grows before it scrolls, and the gap between quests."] = "La largeur du suivi, sa hauteur avant défilement et l'écart entre les quêtes."
L["The typeface."] = "La police de caractères."
L["The unit's level before its name on Blizzard's nameplates, coloured by how hard an enemy is."] = "Le niveau de l'unité avant son nom sur les barres d'info de Blizzard, coloré selon la difficulté de l'ennemi."
L["The unit's level next to its name."] = "Le niveau de l'unité à côté de son nom."
L["The world map turns see-through while you move."] = "La carte du monde devient transparente quand vous bougez."
L["The world map turns see-through while you walk or ride, so you can see where you're going."] = "La carte du monde devient transparente quand vous marchez ou chevauchez, pour voir où vous allez."
L["The XP bar's number format, also used for reputation and honor."] = "Le format des nombres de la barre d'XP, aussi utilisé pour la réputation et l'honneur."
L["The XP your quests will give, in gold on the XP bar. Quests in progress show paler."] = "L'XP que vos quêtes donneront, en or sur la barre d'XP. Les quêtes en cours sont plus pâles."
L["The zone's name along the top of the minimap."] = "Le nom de la zone en haut de la minicarte."
