L[ [=[Want your screen set up like ours? Import the FlareUI layout into Edit Mode:

`1.` Click `Copy layout code` and press `Ctrl+C`.
`2.` Press `Esc` and choose `Edit Mode`.
`3.` Open the `Layout` menu and choose `Import`.
`4.` Paste with `Ctrl+V`, name it and click `Import`.]=] ] = [=[Envie d'un écran comme le nôtre ? Importez la disposition FlareUI dans le Mode Édition :

`1.` Cliquez sur `Copier le code` et appuyez sur `Ctrl+C`.
`2.` Appuyez sur `Échap` et choisissez `Mode Édition`.
`3.` Ouvrez le menu `Disposition` et choisissez `Importer`.
`4.` Collez avec `Ctrl+V`, donnez-lui un nom et cliquez sur `Importer`.]=]
L[ [=[Want your screen set up like ours? Import the FlareUI layout into Edit Mode:

`1.` Click `Copy Layout Code` and press `Ctrl+C`.
`2.` Press `Esc` and choose `Edit Mode`.
`3.` Open the `Layout` menu and choose `Import`.
`4.` Paste with `Ctrl+V`, name it and click `Import`.]=] ] = [=[Envie d'un écran comme le nôtre ? Importez la disposition FlareUI dans le Mode Édition :

`1.` Cliquez sur `Copier le code` et appuyez sur `Ctrl+C`.
`2.` Appuyez sur `Échap` et choisissez `Mode Édition`.
`3.` Ouvrez le menu `Disposition` et choisissez `Importer`.
`4.` Collez avec `Ctrl+V`, donnez-lui un nom et cliquez sur `Importer`.]=]
