L["Your raid in compact tiles that stay centred as the raid grows."] = "Votre raid en tuiles compactes qui restent centrées quand il grandit."
L["Your screen set up the way FlareUI is made to look."] = "Votre écran tel que FlareUI a été pensé."
L["Your threat on an enemy, as a percent, in its tooltip."] = "Votre menace sur un ennemi, en pourcentage, dans son infobulle."
L["Your threat on an enemy, as a percentage, on its tooltip."] = "Votre menace sur un ennemi, en pourcentage, sur son infobulle."
L["Your threat on this unit as a percent, in the threat colours: above the portrait ring, or after the health value in Addon Style."] = "Votre menace sur cette unité en pourcentage, aux couleurs de menace : au-dessus de l'anneau du portrait, ou après la valeur de vie en Style Addon."
L["Your unit frames: you, your target, your party and more."] = "Vos cadres d'unité : vous, votre cible, votre groupe et plus."
L["Your volumes come back when you move, fight or stop fishing for a while."] = "Vos volumes reviennent quand vous bougez, combattez ou cessez de pêcher un moment."
L["Your volumes return when you move, fight or stop fishing for a while."] = "Vos volumes reviennent quand vous bougez, combattez ou arrêtez de pêcher un moment."
L["Your worn gear shows beside an item's tooltip only while you hold Shift."] = "Votre équipement porté s'affiche à côté de l'infobulle d'un objet seulement quand vous maintenez Maj."
L["Zone"] = "Zone"
L["Zone Headings"] = "Titres de zone"
L["Zone headings"] = "Titres de zone"
L["Zone Name"] = "Nom de la zone"
L["Zone name"] = "Nom de la zone"
L["Zone text"] = "Texte de zone"
L["Zone Text"] = "Texte de zone"
L["Zone, clock and coordinates on the map"] = "Zone, horloge et coordonnées sur la carte"
L["Zooms the minimap back out a few seconds after you zoom in."] = "Redézoome la minicarte quelques secondes après un zoom."
L["Zooms the minimap back out a while after you zoom in."] = "Redézoome la minicarte un moment après un zoom."

-- (11-13) phrases added since 6.2
L["* Use Global Font Everywhere: every FlareUI font set to Global, so all text uses the Global Font. Sizes, outlines and shadows stay as they are.\n* Reset All Fonts: every FlareUI font, and the Global Font, back to its defaults."] = "* Police globale partout : toutes les polices de FlareUI en Global, tout le texte prend la Police globale. Tailles, contours et ombres ne changent pas.\n* Réinitialiser les polices : toutes les polices de FlareUI, et la Police globale, reviennent par défaut."
L["%s moves the minimap into its farming HUD while the HUD is on. The map is then the addon's: FlareUI puts its own minimap back when you turn the HUD off.\n\nIf the minimap still looks wrong after that, type /reload."] = "%s déplace la minicarte dans son HUD de récolte tant que le HUD est actif. La carte appartient alors à l'addon : FlareUI remet sa minicarte quand vous désactivez le HUD.\n\nSi la minicarte reste anormale ensuite, tapez /reload."
L["A weapon's or armour's item level at the bottom of its tooltip."] = "Le niveau d'objet d'une arme ou d'une armure en bas de son infobulle."
L["Alignment"] = "Alignement"
L["An arrow beside the backpack folds the other bag slots away, and opens them again. They open by themselves while you carry an item, so you can put it in a bag."] = "Une flèche à côté du sac à dos replie les autres emplacements de sac, et les rouvre. Ils s'ouvrent seuls quand vous portez un objet, pour le ranger dans un sac."
L["An eye in the top right corner marks gear whose appearance you haven't collected yet and can learn."] = "Un œil en haut à droite marque l'équipement dont vous n'avez pas encore l'apparence et que vous pouvez apprendre."
L["Apply to All"] = "Appliquer à tous"
L["Apply to Both"] = "Appliquer aux deux"
L["Bars Appearance"] = "Apparence des barres"
L["Blizzard's own text takes the Global Font too: menus, windows, quest text, nameplates, combat text and more. Sizes and outlines stay as they are."] = "Le texte de Blizzard prend aussi la Police globale : menus, fenêtres, texte des quêtes, barres de nom, texte de combat et plus. Tailles et contours ne changent pas."
L["Borderless Bag Bar"] = "Barre de sacs sans cadre"
L["Borderless Micro Menu"] = "Micro-menu sans cadre"
L["Button Names"] = "Noms des boutons"
L["Cast Countdown"] = "Compte à rebours"
L["Cast Name"] = "Nom du sort"
L["Collapsible Bag Bar"] = "Barre de sacs repliable"
L["Combat Text Font"] = "Police du texte de combat"
L["Copy this frame's fonts to every frame of its kind?\n\n%s"] = "Copier les polices de ce cadre sur tous ceux du même type ?\n\n%s"
L["Counts"] = "Nombres"
L["Don't Show on Login"] = "Ne pas afficher à la connexion"
L["Drag to move this button."] = "Faites glisser pour déplacer ce bouton."
L["Druids keep their Cat Form page while prowling. Off, Prowl turns to the prowl page, as Stealth does for rogues."] = "Les druides gardent la page de Forme de félin en rôdant. Désactivé, Rôder passe à la page de rôder, comme Camouflage pour les voleurs."
L["Each bar's font is in its Edit Mode dialog: select a bar, then open Fonts, the last section. Apply to All there gives every bar the same font."] = "La police de chaque barre est dans sa fenêtre du Mode Édition : sélectionnez une barre, puis ouvrez Polices, la dernière section. Appliquer à tous y donne la même police à toutes les barres."
L["Each frame's fonts are in its Edit Mode dialog: select a frame, then open Fonts, the last section. Apply to All there gives every unit frame the same fonts."] = "Les polices de chaque cadre sont dans sa fenêtre du Mode Édition : sélectionnez un cadre, puis ouvrez Polices, la dernière section. Appliquer à tous y donne les mêmes polices à tous les cadres d'unité."
L["Every resource bar takes this bar's font."] = "Toutes les barres de ressource prennent la police de cette barre."
L["Every unit frame takes this frame's fonts: player, target, focus, pets, party, raid and boss."] = "Tous les cadres d'unité prennent les polices de celui-ci : joueur, cible, focalisation, familiers, groupe, raid et boss."
L["Every unit frame's cast bar takes this font."] = "La barre d'incantation de chaque cadre d'unité prend cette police."
L["Farming HUDs"] = "HUD de récolte"
L["FlareUI's square minimap with its buttons and zone name on the map (Clean) or in the frame's bronze title bar (Header), or Forever's own round one. Changing to or from Round reloads the interface."] = "La minicarte carrée de FlareUI avec ses boutons et le nom de la zone sur la carte (Épurée) ou dans la barre de titre en bronze (En-tête), ou la minicarte ronde de Forever. Passer à Ronde ou en revenir recharge l'interface."
L["ForeverFarmHUD and FarmHud move the minimap into their HUD while it is on. FlareUI puts its own minimap back when you turn the HUD off; if it still looks wrong, type /reload."] = "ForeverFarmHUD et FarmHud déplacent la minicarte dans leur HUD tant qu'il est actif. FlareUI remet sa minicarte quand vous désactivez le HUD ; si elle reste anormale, tapez /reload."
L["Game Text"] = "Texte du jeu"
L["Global (%s)"] = "Global (%s)"
L["Global Font"] = "Police globale"
L["How dark the tooltips' background is."] = "L'opacité du fond des infobulles."
L["Info Text"] = "Texte d'info"
L["Item counts and spell charges on the buttons."] = "Nombre d'objets et charges de sorts sur les boutons."
L["Item Level"] = "Niveau d'objet"
L["Item Level %d"] = "Niveau d'objet %d"
L["Latency"] = "Latence"
L["Level"] = "Niveau"
L["Nameplate Font"] = "Police des barres de nom"
L["Names"] = "Noms"
L["Needs Borderless Bag Bar. Edit Mode's Orientation and Direction for the bag bar turn the arrow too."] = "Nécessite Barre de sacs sans cadre. L'orientation et la direction de la barre de sacs en Mode Édition tournent aussi la flèche."
L["No frame round the bag bar, and no dividers between the bags. Its frame only fits the default place."] = "Pas de cadre autour de la barre de sacs, ni de séparateurs entre les sacs. Son cadre ne va qu'à l'emplacement par défaut."
L["No frame round the micro menu. Its frame only fits the default place."] = "Pas de cadre autour du micro-menu. Son cadre ne va qu'à l'emplacement par défaut."
L["On the character sheet it works with another bag addon too."] = "Sur la fiche de personnage, il marche aussi avec un autre addon de sacs."
L["Percent <  > Value"] = "Pourcentage <  > Valeur"
L["Percent | Value"] = "Pourcentage | Valeur"
L["Preview only — click to apply"] = "Aperçu seulement — cliquez pour appliquer"
L["Put every FlareUI font, and the Global Font, back to its defaults?"] = "Remettre toutes les polices de FlareUI, et la Police globale, par défaut ?"
L["Remember"] = "Mémoriser"
L["Reset All Fonts"] = "Réinit. toutes les polices"
L["Reset Fonts"] = "Réinitialiser les polices"
L["Reset on Close"] = "Réinitialiser à la fermeture"
L["Right-click: put back in the drawer"] = "Clic droit : remettre dans le tiroir"
L["Rogues and druids: Action Bar 1 keeps the same buttons in Stealth or Prowl, instead of the stealth page."] = "Voleurs et druides : la barre d'action 1 garde les mêmes boutons en Camouflage ou en Rôder, au lieu de la page de camouflage."
L["Russian, Korean and Chinese letters keep a font that has them. FlareUI's own font choices still go over it."] = "Les lettres russes, coréennes et chinoises gardent une police qui les contient. Vos polices FlareUI restent par-dessus."
L["Screen Text"] = "Texte à l'écran"
L["Separate Window"] = "Fenêtre séparée"
L["Set every FlareUI font to the Global Font?\n\nEach font keeps its size, outline and shadow."] = "Mettre toutes les polices de FlareUI sur la Police globale ?\n\nChaque police garde sa taille, son contour et son ombre."
L["Short item stats, like \"+12 Spell Power\" instead of the long \"Equip: Increases…\" line. Set bonuses too."] = "Statistiques d'objet courtes, comme « +12 puissance des sorts » au lieu de la longue ligne « Équipé : Augmente… ». Bonus d'ensemble aussi."
L["Show Item Level"] = "Afficher le niveau d'objet"
L["Square (Clean)"] = "Carrée (épurée)"
L["Square (Header)"] = "Carrée (en-tête)"
L["Sub-Radials"] = "Sous-radiaux"
L["The Buffs and Debuffs fonts are in their Edit Mode dialogs: select one, then open Fonts, the last section. Apply to Both there gives the other the same fonts."] = "Les polices des buffs et débuffs sont dans leurs fenêtres du Mode Édition : sélectionnez-en un, puis ouvrez Polices, la dernière section. Appliquer aux deux y donne les mêmes polices à l'autre."
L["The damage and healing numbers over what you hit. Default keeps Blizzard's font."] = "Les chiffres de dégâts et de soins au-dessus de ce que vous frappez. Par défaut garde la police de Blizzard."
L["The font for every FlareUI text set to Global, in one place. Pick Global in any Fonts tab to make that text follow it."] = "La police de tout texte de FlareUI réglé sur Global, en un seul endroit. Choisissez Global dans n'importe quel onglet Polices pour que ce texte la suive."
L["The game reads it as you log in: it changes the next time you log in."] = "Le jeu la lit à la connexion : elle change à votre prochaine connexion."
L["The gold, silver and copper at the bottom of your bags. Default keeps Blizzard's font."] = "L'or, l'argent et le cuivre au bas de vos sacs. Par défaut garde la police de Blizzard."
L["The name of the button you point at."] = "Le nom du bouton que vous visez."
L["The names on Blizzard's nameplates. Default keeps their font (or the Global Font, with Game Text on)."] = "Les noms sur les barres de nom de Blizzard. Par défaut garde leur police (ou la Police globale, avec Texte du jeu activé)."
L["The notes stay here, under What's New."] = "Les notes restent ici, dans Nouveautés."
L["The numbers on the XP and reputation bar."] = "Les nombres sur la barre d'XP et de réputation."
L["The other frame (Buffs or Debuffs) takes this frame's fonts."] = "L'autre cadre (buffs ou débuffs) prend les polices de celui-ci."
L["The reminders you hid with a right-click. Untick one to bring it back; None brings them all back."] = "Les rappels masqués d'un clic droit. Décochez-en un pour le remettre ; Aucun les remet tous."
L["The size of the whole interface, for every character:\n* Off: FlareUI leaves it alone, and Blizzard's UI Scale setting works\n* Pixel Perfect: one interface pixel per screen pixel\n* 4K, 1440p, 1080p: pixel perfect for that screen (at 125% for Windows' 125% scaling)\n* Custom: any scale, beyond Blizzard's slider\nAny choice but Off replaces Blizzard's UI Scale each time you log in."] = "La taille de toute l'interface, pour chaque personnage :\n* Désactivé : FlareUI n'y touche pas, et l'échelle d'interface de Blizzard fonctionne\n* Pixel parfait : un pixel d'interface par pixel d'écran\n* 4K, 1440p, 1080p : pixel parfait pour cet écran (à 125 % pour la mise à l'échelle 125 % de Windows)\n* Personnalisé : n'importe quelle échelle, au-delà du curseur de Blizzard\nTout choix sauf Désactivé remplace l'échelle de Blizzard à chaque connexion."
L["The tracker's fonts are in its Edit Mode dialog: select the tracker, then open Fonts, the last section."] = "Les polices du suivi sont dans sa fenêtre du Mode Édition : sélectionnez le suivi, puis ouvrez Polices, la dernière section."
L["The typeface. Global follows the Global Font on the Settings page."] = "Le caractère. Global suit la Police globale de la page Paramètres."
L["The zone name, clock and info text fonts are in the minimap's Edit Mode dialog: select the minimap, then open Fonts, the last section."] = "Les polices du nom de zone, de l'horloge et du texte d'info sont dans la fenêtre de la minicarte en Mode Édition : sélectionnez la minicarte, puis ouvrez Polices, la dernière section."
L["These settings are disabled in Gamepad mode due to Blizzard restrictions."] = "Ces paramètres sont désactivés en mode Manette à cause des restrictions de Blizzard."
L["This class's own reminders. Untick one to remove it; None removes them all."] = "Les rappels propres à cette classe. Décochez-en un pour le retirer ; Aucun les retire tous."
L["This frame's fonts back to their defaults."] = "Les polices de ce cadre reviennent par défaut."
L["Threat in a window of its own instead of a tab on the Damage Meter. Move and size it in Edit Mode; it shows and hides with the Damage Meter."] = "La menace dans sa propre fenêtre au lieu d'un onglet du compteur de dégâts. Déplacez-la et dimensionnez-la en Mode Édition ; elle s'affiche et se masque avec le compteur."
L["Uncollected Appearances"] = "Apparences non collectées"
L["Use Global Font"] = "Utiliser la Police globale"
L["Use Global Font Everywhere"] = "Police globale partout"
L["Value [Max]"] = "Valeur [Max]"
L["Value | Health Lost"] = "Valeur | Vie perdue"
L["Weapons and armour show their item level in the bottom left corner, in their quality's colour: in your bags and on the character sheet."] = "Les armes et armures affichent leur niveau d'objet en bas à gauche, à la couleur de leur qualité : dans vos sacs et sur la fiche de personnage."
L["Which button a sub-radial shows when you open the radial again:\n* Reset on Close: its first button\n* Remember: the one you scrolled to last"] = "Le bouton qu'un sous-radial montre quand vous rouvrez le radial :\n* Réinitialiser à la fermeture : son premier bouton\n* Mémoriser : celui où vous étiez"
L["Which side the icons sit on:\n* Left: icon, then the text\n* Right: the text, then the icon, lined up on the right (at the cursor: to its left)"] = "De quel côté sont les icônes :\n* Gauche : l'icône, puis le texte\n* Droite : le texte, puis l'icône, alignés à droite (au curseur : à sa gauche)"
L["Which text the rows below change."] = "Quel texte les options ci-dessous changent."
L["Your latency at the minimap's bottom right: home on top, world below. With Framerate, the one shown always sits at the bottom."] = "Votre latence en bas à droite de la minicarte : domicile en haut, monde en dessous. Avec Images/s, celle qui reste affichée est toujours en bas."
L["Flip Portrait"] = "Retourner le portrait"
L["The portrait faces the other way."] = "Le portrait regarde de l'autre côté."
L["Mirror Bars"] = "Barres en miroir"
L["Each frame style keeps its own fonts."] = "Chaque style de cadre garde ses propres polices."
L["Each quest's name."] = "Le nom de chaque quête."
L["Every other bar takes this bar's font."] = "Toutes les autres barres prennent la police de cette barre."
L["How long the buff has left, on each icon."] = "Le temps restant de l'amélioration, sur chaque icône."
L["Raid and Main Tanks"] = "Raid et tanks principaux"
L["The coordinates and other small text on the map."] = "Les coordonnées et les autres petits textes de la carte."
L["The lines under each quest."] = "Les lignes sous chaque quête."
L["The number on each icon."] = "Le nombre sur chaque icône."
L["The numbers or time left on this bar."] = "Les nombres ou le temps restant sur cette barre."
L["The spell's name on the cast bar."] = "Le nom du sort sur la barre d'incantation."
L["The stack count on buffs and debuffs. Auto sizes it to the icon."] = "Les cumuls des buffs et débuffs. Auto l'adapte à l'icône."
L["The time left on buffs and debuffs. Auto sizes it to the icon."] = "Le temps restant des buffs et débuffs. Auto l'adapte à l'icône."
L["The time left on the cast bar."] = "Le temps restant sur la barre d'incantation."
L["The time on the map's clock."] = "L'heure sur l'horloge de la carte."
L["The tracker's title and its headers."] = "Le titre du suivi et ses en-têtes."
L["The unit's level."] = "Le niveau de l'unité."
L["The unit's name."] = "Le nom de l'unité."
L["The zone's name above the map."] = "Le nom de la zone au-dessus de la carte."
L["In an Instance"] = "En instance"
L["Needs Separate Window. It never shows while the Damage Meter is hidden."] = "Nécessite Fenêtre séparée. Ne s'affiche jamais quand le compteur de dégâts est masqué."
L["When the threat window shows.\n* With the Meter: whenever the Damage Meter shows\n* In an Instance: in dungeons, raids, battlegrounds and arenas\n* In a Group: while you're in a group\n* In Combat: during fights"] = "Quand la fenêtre de menace s'affiche.\n* Avec le compteur : chaque fois que le compteur de dégâts s'affiche\n* En instance : en donjons, raids, champs de bataille et arènes\n* En groupe : quand vous êtes en groupe\n* En combat : pendant les combats"
L["With the Meter"] = "Avec le compteur"
L[ [=[When the meter shows.
* In Combat: during fights
* In a Group: while you're in a group
* In an Instance: in dungeons, raids, battlegrounds and arenas
* Hidden: never on its own]=] ] = [=[Quand le compteur s'affiche.
* En combat : pendant les combats
* En groupe : tant que vous êtes en groupe
* En instance : en donjons, raids, champs de bataille et arènes
* Masqué : jamais tout seul]=]
L["Finished objectives stay on the list."] = "Les objectifs terminés restent dans la liste."
L["Macro names on their buttons."] = "Le nom des macros sur leurs boutons."
L["Show Completed Objectives"] = "Afficher les objectifs terminés"
L["Show Keybind Text"] = "Afficher les raccourcis"
L["Show Macro Text"] = "Afficher le texte des macros"
L["Show Quest Level"] = "Afficher le niveau de quête"
L["Show Spell Timer"] = "Afficher le temps du sort"
L["The key for each button, on the button."] = "La touche de chaque bouton, sur le bouton."
L["The quest's level in front of its name."] = "Le niveau de la quête devant son nom."
L["The spell's icon, left of the bar."] = "L'icône du sort, à gauche de la barre."
L["The time left, at the right end of the bar."] = "Le temps restant, à l'extrémité droite de la barre."
L["* Use Global Font Everywhere: sets every FlareUI font to Global. Sizes, outlines and shadows stay as they are.\n* Reset All Fonts: every FlareUI font, and the Global Font, back to defaults."] = "* Police globale partout : passe toutes les polices FlareUI sur Global. Tailles, contours et ombres ne changent pas.\n* Réinit. toutes les polices : toutes les polices FlareUI, et la Police globale, reviennent par défaut."
L["/fui pad still switches. It never asks while ConsolePort or another controller addon is loaded."] = "/fui pad change toujours de mode. Aucune question tant que ConsolePort ou un autre addon de manette est chargé."
L["A Blizzard setting: it only changes out of combat."] = "Un réglage Blizzard : il ne change que hors combat."
L["A brighter arc over the ring fills as you cast and empties as you channel."] = "Un arc plus clair sur l'anneau se remplit pendant l'incantation et se vide pendant la canalisation."
L["A button beside the bags' cleanup button opens a drawer of filters:\n* Quest Items\n* Equipment\n* Materials\n* Consumables\nPick one and everything else dims."] = "Un bouton à côté du bouton de rangement des sacs ouvre un tiroir de filtres :\n* Objets de quête\n* Équipement\n* Matériaux\n* Consommables\nChoisissez-en un et tout le reste s'assombrit."
L["A mark near the end of the bar. Press your next spell after it and it goes off right as this one ends."] = "Une marque près de la fin de la barre. Lancez votre sort suivant après elle et il part pile à la fin de celui-ci."
L["A short tag after the quest name:\n* + for elite\n* g3 for a group of 3\n* d for dungeon, r for raid\n* pvp for PvP"] = "Une petite étiquette après le nom de la quête :\n* + pour élite\n* g3 pour un groupe de 3\n* d pour donjon, r pour raid\n* pvp pour JcJ"
L["A spark crosses the bar for five seconds after you spend mana. Spirit regeneration starts again when it ends."] = "Une étincelle traverse la barre pendant cinq secondes après une dépense de mana. La régénération par l'Esprit reprend à la fin."
L["A tab you click stays up until the condition changes, like a fight ending."] = "Un onglet cliqué reste affiché jusqu'à ce que la condition change, par exemple la fin d'un combat."
L["Always clears the others; nothing ticked means Always. Fake CM Setup Mode always shows them."] = "Toujours décoche les autres ; rien de coché équivaut à Toujours. Le Mode configuration du Fake CM les affiche toujours."
L["An arrow beside the backpack hides and shows the other bag slots. They open on their own while you hold an item on the cursor, so you can drop it in a bag."] = "Une flèche à côté du sac à dos masque et affiche les autres emplacements de sac. Ils s'ouvrent d'eux-mêmes quand vous tenez un objet sur le curseur, pour le déposer dans un sac."
L["An icon for each debuff type you can dispel, two to a row, in the middle of the portrait. Without a portrait, in the middle of the health bar."] = "Une icône par type de débuff que vous pouvez dissiper, deux par ligne, au milieu du portrait. Sans portrait, au milieu de la barre de vie."
L["An icon when you know Find Herbs or Find Minerals but it's off."] = "Une icône quand vous connaissez Découverte d'herbes ou Découverte de gisements mais qu'il est désactivé."
L["An icon while you have no Well Fed buff or no flask. Choose where it shows on the When and Where tab."] = "Une icône tant que vous n'avez ni le buff Bien nourri ni flacon. Choisissez où elle s'affiche dans l'onglet Quand et où."
L["An unticked addon's button goes back to the minimap after a reload. New addons go in the drawer."] = "Le bouton d'un addon décoché retourne sur la minicarte après un rechargement. Les nouveaux addons vont dans le tiroir."
L["Aura timers turn yellow under 10 seconds and red under 5, on every unit frame."] = "Les durées des auras passent en jaune sous 10 secondes et en rouge sous 5, sur tous les cadres d'unité."
L["Class buffs you're reminded of only if you tick them: Shadow Protection and Moonkin Form."] = "Buffs de classe rappelés seulement si vous les cochez : Protection contre l'Ombre et Forme de sélénien."
L["Classic: the player frame's look. Raid Style: compact tiles with the auras inside. Each style keeps its own settings."] = "Classique : l'apparence du cadre du joueur. Style raid : tuiles compactes avec les auras dedans. Chaque style garde ses propres réglages."
L["Cleaner tooltips with coloured borders that can follow your mouse."] = "Infobulles plus nettes, aux bordures colorées, qui peuvent suivre la souris."
L["Debuffs on the boss. With Only My Debuffs, just yours."] = "Les débuffs sur le boss. Avec Seulement mes débuffs, juste les vôtres."
L["Doesn't apply with While Right-Clicking, which shows the ring while you turn."] = "Ne s'applique pas avec Pendant le clic droit, qui affiche l'anneau pendant que vous tournez."
L["Doesn't work in combat or in battlegrounds, where the game keeps the map's clicks."] = "Ne marche pas en combat ni en champ de bataille, où le jeu garde les clics de la carte."
L["Doesn't work in combat or in the Gamepad UI."] = "Ne marche pas en combat ni dans l'interface manette."
L["Druids: a thin mana bar under the power bar, in forms without mana. The health bar gets shorter to make room."] = "Druides : une fine barre de mana sous la barre de puissance, dans les formes sans mana. La barre de vie raccourcit pour faire de la place."
L["Each item's border takes its quality colour."] = "La bordure de chaque objet prend la couleur de sa qualité."
L["Edit Mode's Icon Size still changes each bar's size on top of this."] = "La Taille des icônes du Mode Édition change toujours la taille de chaque barre en plus de ceci."
L["Every resource bar colour in one window, next to the bars. Palettes:\n* FlareUI (default)\n* Blizzard"] = "Toutes les couleurs des barres de ressource dans une fenêtre, à côté des barres. Palettes :\n* FlareUI (par défaut)\n* Blizzard"
L["Every unit frame colour in one window, next to the frames. Palettes:\n* FlareUI: softer, darker tones (default)\n* Blizzard: the game's own"] = "Toutes les couleurs des cadres d'unité dans une fenêtre, à côté des cadres. Palettes :\n* FlareUI : tons plus doux et plus sombres (par défaut)\n* Blizzard : celles du jeu"
L["FlareUI's border in place of the bronze frame on every bar's buttons: main, pet, stance, possess, totem and vehicle bars. Only the border changes."] = "La bordure FlareUI à la place du cadre bronze sur les boutons de toutes les barres : principale, familier, posture, contrôle, totems et véhicule. Seule la bordure change."
L["For example: /way 45 60 or /way Elwynn Forest 45 60."] = "Par exemple : /way 45 60 ou /way Forêt d'Elwynn 45 60."
L["For example: one group for your bottom bars, another for your side bars."] = "Par exemple : un groupe pour vos barres du bas, un autre pour vos barres latérales."
L["Hides the tracker while nothing is tracked."] = "Masque le suivi quand rien n'est suivi."
L["How aura icons show their time left, on every unit frame."] = "Comment les icônes d'aura affichent leur temps restant, sur tous les cadres d'unité."
L["How aura icons show their time left."] = "Comment les icônes d'aura affichent leur temps restant."
L["Import shows the string's version, UI scale and any fonts or textures you're missing, then reloads. To share Edit Mode layouts, use Edit Mode."] = "L'import affiche la version de la chaîne, l'échelle de l'interface et les polices ou textures manquantes, puis recharge. Pour partager des dispositions du Mode Édition, passez par le Mode Édition."
L["In your bags and on the character sheet, weapons and armour show their item level in the bottom left corner, in their quality colour."] = "Dans vos sacs et sur la fiche de personnage, armes et armures affichent leur niveau d'objet en bas à gauche, à la couleur de leur qualité."
L["It changes the next time you log in."] = "Le changement prend effet à la prochaine connexion."
L["Laid out like the target frame: portrait on the right, bars filling from the right. In FlareUI and Forever Style, only the bars flip."] = "Disposé comme le cadre de la cible : portrait à droite, barres remplies depuis la droite. En Style FlareUI et Style Forever, seules les barres s'inversent."
L["Leaves long buffs off the raid frames:\n* Permanent: buffs with no duration\n* Longer Than: buffs whose full duration is longer, and permanent ones"] = "Retire les buffs longs des cadres de raid :\n* Permanents : buffs sans durée\n* Plus de… : buffs dont la durée totale est plus longue, et les permanents"
L["Leaves long buffs off this frame:\n* Permanent: buffs with no duration\n* Longer Than: buffs whose full duration is longer, and permanent ones"] = "Retire les buffs longs de ce cadre :\n* Permanents : buffs sans durée\n* Plus de… : buffs dont la durée totale est plus longue, et les permanents"
L["Linked to Blizzard's own Coordinates option: turning one off turns off the other."] = "Lié à l'option Coordonnées de Blizzard : désactiver l'une désactive l'autre."
L["Marks the swing's last half second. Auto Shot and wands need you to stand still then."] = "Marque la dernière demi-seconde du coup. Tir automatique et les baguettes demandent alors de rester immobile."
L["Middle-click a folded quest to open it. It stays open."] = "Clic milieu sur une quête repliée pour l'ouvrir. Elle reste ouverte."
L["Minimizes the tracker during fights. It opens again after the fight."] = "Réduit le suivi pendant les combats. Il se rouvre après le combat."
L["Minimizes the tracker in dungeons, raids, battlegrounds and arenas. It opens again when you leave."] = "Réduit le suivi en donjon, en raid, en champ de bataille et en arène. Il se rouvre quand vous en sortez."
L["Next to the timer: how far hits pushed your cast back or cut your channel short, like \"+0.5\"."] = "À côté du chrono : de combien les coups ont repoussé votre incantation ou écourté votre canalisation, par ex. \"+0.5\"."
L["No frame round the bag bar, and no dividers between the bags. Blizzard's frame only fits the bar in its default place."] = "Pas de cadre autour de la barre des sacs, ni de séparateurs entre les sacs. Le cadre de Blizzard ne va à la barre qu'à sa place par défaut."
L["No frame round the micro menu. Blizzard's frame only fits the menu in its default place."] = "Pas de cadre autour du micro-menu. Le cadre de Blizzard ne va au menu qu'à sa place par défaut."
L["Pixel Perfect keeps borders and thin lines sharpest. Text is sharp at any scale. Changing it reloads the interface."] = "Pixel parfait garde les bordures et les lignes fines plus nettes. Le texte est net à toute échelle. Le changer recharge l'interface."
L["Power bars only for classes that use mana. Warriors and rogues get the room for health instead."] = "Barres de puissance seulement pour les classes à mana. Guerriers et voleurs gagnent la place pour la vie."
L["Right-click a colour to put it back."] = "Clic droit sur une couleur pour la remettre par défaut."
L["Rogues and druids: Action Bar 1 doesn't turn to the stealth page in Stealth or Prowl. Druids keep their Cat Form page."] = "Voleurs et druides : la Barre d'action 1 ne passe pas sur la page de camouflage en Camouflage ou Rôder. Les druides gardent leur page de Forme de félin."
L["Short item stats, like \"+12 Spell Power\" instead of the long \"Equip: Increases…\" line. Set bonuses are shortened too."] = "Stats d'objet courtes, comme \"+12 puissance des sorts\" au lieu de la longue ligne \"Équipé : Augmente…\". Les bonus d'ensemble sont aussi raccourcis."
L["Surnames after first names on:\n* Player and target frames\n* Party and focus frames, in Forever Style"] = "Noms de famille après les prénoms sur :\n* Les cadres du joueur et de la cible\n* Les cadres de groupe et du focus, en Style Forever"
L["Target of target and target of focus always show first names."] = "La cible de la cible et la cible du focus affichent toujours les prénoms."
L["The bar turns red while your target is out of reach of this attack."] = "La barre passe au rouge quand votre cible est hors de portée de cette attaque."
L["The border around the chat and its edit box. None hides it."] = "La bordure autour du chat et de sa zone de saisie. Aucun la masque."
L["The border around the meter. None hides it."] = "La bordure autour du compteur. Aucun la masque."
L["The border around the tracker. None hides it."] = "La bordure autour du suivi. Aucun la masque."
L["The cast bar's border. Frame Border matches the frame's own border."] = "La bordure de la barre d'incantation. Bordure du cadre reprend la bordure du cadre lui-même."
L["The edge that stays put as the tracker grows:\n* Automatic: whichever edge is nearer the edge of the screen\n* Top: grows downward\n* Bottom: grows upward"] = "Le bord qui reste fixe quand le suivi grandit :\n* Automatique : le bord le plus proche du bord de l'écran\n* Haut : grandit vers le bas\n* Bas : grandit vers le haut"
L["The encounter's bosses, mirrored like the target frame."] = "Les boss de la rencontre, en miroir comme le cadre de la cible."
L["The font for all FlareUI text set to Global. Pick Global in any Fonts tab to make that text use it."] = "La police de tout le texte FlareUI réglé sur Global. Choisissez Global dans n'importe quel onglet Polices pour que ce texte l'utilise."
L["The frame fades while the unit is out of range."] = "Le cadre s'estompe quand l'unité est hors de portée."
L["The gryphons at the ends of the main bar sit behind your action bars, not over them."] = "Les griffons aux bouts de la barre principale passent derrière vos barres d'action, pas par-dessus."
L["The meter takes the chat's width and height. Off: it goes back to its Edit Mode size."] = "Le compteur prend la largeur et la hauteur du chat. Désactivé : il reprend sa taille du Mode Édition."
L["The minimap's look. Changing to or from Round reloads the interface.\n* Square (Clean): FlareUI's square minimap, with its buttons and zone name on the map\n* Square (Header): the same, with the buttons and zone name in a bronze title bar\n* Round: Forever's own round minimap"] = "L'apparence de la minicarte. Passer à Rond ou en sortir recharge l'interface.\n* Carrée (épurée) : la minicarte carrée de FlareUI, avec ses boutons et le nom de zone sur la carte\n* Carrée (en-tête) : pareil, avec les boutons et le nom de zone dans une barre de titre bronze\n* Rond : la minicarte ronde de Forever"
L["The number on a group buff's icon: how many are missing it, out of how many."] = "Le nombre sur l'icône d'un buff de groupe : combien ne l'ont pas, sur combien."
L["The pet frame fades with the player frame, using these settings. Pointing at either shows both."] = "Le cadre du familier s'estompe avec celui du joueur, avec ces réglages. Pointer l'un affiche les deux."
L["The plain pet frame in every style. Off: a small pet frame in Forever or FlareUI Style."] = "Le cadre de familier simple dans tous les styles. Désactivé : un petit cadre de familier en Style Forever ou Style FlareUI."
L["The plain target of target and target of focus frames in every style. Off: small frames in Forever or FlareUI Style."] = "Les cadres simples de cible de la cible et de cible du focus dans tous les styles. Désactivé : petits cadres en Style Forever ou Style FlareUI."
L["The Remind Before It Ends time inside dungeons. Same as Above uses the time above."] = "Le délai Rappeler avant la fin en donjon. Idem au-dessus reprend le délai du dessus."
L["The Remind Before It Ends time inside raids. Same as Above uses the time above."] = "Le délai Rappeler avant la fin en raid. Idem au-dessus reprend le délai du dessus."
L["The reminders you hid with a right-click. Untick one to bring it back. None brings them all back."] = "Les rappels masqués d'un clic droit. Décochez-en un pour le faire revenir. Aucun les fait tous revenir."
L["The XP your quests will give, in gold on the XP bar. Quests in progress show paler. The total also shows in the bar's text."] = "L'XP que vos quêtes vont rapporter, en doré sur la barre d'XP. Les quêtes en cours sont plus pâles. Le total s'affiche aussi dans le texte de la barre."
L["The zone name that appears as you enter a new area. Default keeps Blizzard's font. The size stays the same."] = "Le nom de zone qui apparaît quand vous entrez dans une nouvelle zone. Par défaut garde la police de Blizzard. La taille ne change pas."
L["These tooltips at your mouse instead of the default spot. It matches Mouseover on the Settings tab unless you change it here."] = "Ces infobulles à la souris au lieu de l'emplacement par défaut. Suit Survol de l'onglet Paramètres sauf si vous le changez ici."
L["Threat in its own window instead of a tab on the Damage Meter. Move and size it in Edit Mode."] = "La menace dans sa propre fenêtre au lieu d'un onglet du Compteur de dégâts. Déplacez-la et redimensionnez-la dans le Mode Édition."
L["Tick the addons whose buttons go in the drawer. The others stay on the minimap, where their addon puts them."] = "Cochez les addons dont les boutons vont dans le tiroir. Les autres restent sur la minicarte, là où leur addon les place."
L["To change one kind of tooltip only, use the Visibility tab. Changing this switch clears those changes."] = "Pour changer un seul type d'infobulle, passez par l'onglet Visibilité. Changer cet interrupteur efface ces changements."
L["To put it on the player frame instead, turn on Cast Bar in the player frame's Edit Mode options."] = "Pour la mettre sur le cadre du joueur, activez Barre d'incantation dans les options du Mode Édition du cadre du joueur."
L["Tooltips on the buff and debuff icons of party and raid frames. Never: pointing at an icon counts as pointing at the frame."] = "Infobulles sur les icônes de buffs et débuffs des cadres de groupe et de raid. Jamais : pointer une icône compte comme pointer le cadre."
L["Turns this bar into part of a cooldown display:\n* Not clickable\n* Shows only by the Fake CM Visibility"] = "Fait de cette barre une partie d'un affichage de recharges :\n* Non cliquable\n* S'affiche seulement selon la Visibilité du Fake CM"
L["Until you pick a palette here, the bars follow the unit frames' palette."] = "Tant que vous n'avez pas choisi de palette ici, les barres suivent celle des cadres d'unité."
L["When auto attack is on but you can't swing (the target is out of reach), the bar shows full and grey, with Waiting."] = "Quand l'attaque auto est active mais que vous ne pouvez pas frapper (cible hors de portée), la barre est pleine et grise, avec En attente."
L["When the meter shows.\n* Always: all the time\n* In Combat: during fights\n* In a Group: while you're in a group\n* In an Instance: in dungeons, raids, battlegrounds and arenas\n* Hidden: never on its own"] = "Quand le compteur s'affiche.\n* Toujours : tout le temps\n* En combat : pendant les combats\n* En groupe : quand vous êtes en groupe\n* En instance : en donjon, raid, champ de bataille et arène\n* Masqué : jamais de lui-même"
L["Where it shows is set by Consumables on the When and Where tab, as for Food and Flask."] = "L'endroit où il s'affiche dépend de Consommables dans l'onglet Quand et où, comme pour Nourriture et flacon."
L["Where reminders show for a missing, dead or hurt pet."] = "Où s'affichent les rappels pour un familier absent, mort ou blessé."
L["Where reminders show for food, flasks and elixirs."] = "Où s'affichent les rappels pour la nourriture, les flacons et les élixirs."
L["Where reminders show for weapon buffs: poisons, imbues, stones and oils."] = "Où s'affichent les rappels pour les buffs d'arme : poisons, imprégnations, pierres et huiles."
L["Where reminders show for your class's own buffs."] = "Où s'affichent les rappels pour les buffs de votre classe."
L["Which oil or stone the Weapon Oil / Stone reminder picks first:\n* Melee and Tank: stones\n* Caster: wizard oil\n* Healer: mana oil\n* Automatic: by your group role, then your class"] = "L'huile ou la pierre que le rappel Huile / pierre d'arme choisit en premier :\n* Mêlée et Tank : pierres\n* Lanceur de sorts : huile de sorcier\n* Soigneur : huile de mana\n* Automatique : selon votre rôle de groupe, puis votre classe"
L["Which way the raid grows as groups join, one row per group. The main tank frames follow it."] = "Le sens dans lequel le raid grandit quand des groupes arrivent, une ligne par groupe. Les cadres des tanks principaux suivent."
L["Works with Show on Mouseover. With Meter Tab in the Chat on, Open the Meter Tab decides instead."] = "Marche avec Afficher au survol. Avec Onglet Compteur dans le chat activé, c'est Ouvrir l'onglet Compteur qui décide."
L["Your bag slots down the side of the combined backpack:\n* Drag bags in and out\n* Point at one to highlight its items"] = "Vos emplacements de sac le long du sac à dos combiné :\n* Glissez des sacs dedans et dehors\n* Pointez-en un pour surligner ses objets"
L["Your cast bar as its own frame, in FlareUI's style. Off: Blizzard's cast bar."] = "Votre barre d'incantation dans son propre cadre, au style FlareUI. Désactivé : la barre d'incantation de Blizzard."
L["Your latency at the minimap's bottom right: home on top, world below. With Framerate on as well, the one set to Always sits at the bottom."] = "Votre latence en bas à droite de la minicarte : locale en haut, monde en dessous. Avec Images/s activé aussi, celui réglé sur Toujours se met en bas."
L["Your latency, in red at the end of the bar. Press your next spell there and it goes off as this one ends."] = "Votre latence, en rouge au bout de la barre. Lancez votre sort suivant là et il part à la fin de celui-ci."
L["Your own reminders for this class. Untick one to remove it. None removes them all."] = "Vos propres rappels pour cette classe. Décochez-en un pour le retirer. Aucun les retire tous."
L["Your threat on this unit as a percent, in threat colours. Above the portrait ring, or after the health value in Addon Style."] = "Votre menace sur cette unité en pourcentage, aux couleurs de menace. Au-dessus de l'anneau du portrait, ou après la valeur de vie en Style Addon."
L["Outlines a member with a debuff that can be removed:\n* Dispellable by Me: what you can remove\n* Dispellable by the Group: what anyone can remove"] = "Entoure un membre qui a un débuff retirable :\n* Dispellable par moi : ce que vous pouvez retirer\n* Dispellable par le groupe : ce que n'importe qui peut retirer"
L["With a sort that puts new icons in the middle, it can play on the last icon instead of the new one."] = "Avec un tri qui place les nouvelles icônes au milieu, elle peut se jouer sur la dernière icône au lieu de la nouvelle."
L["Gamepad mode: the stick press that opens this radial. Click, then press L3 or R3, alone or with LT, RT or both held."] = "Mode manette : l'appui de stick qui ouvre ce radial. Cliquez, puis appuyez sur L3 ou R3, seul ou avec LT, RT ou les deux maintenus."
L["Gamepad mode: puts this radial on a controller bar slot. Click, then press A, B, X, Y or the D-pad, alone or with LT, RT or both held."] = "Mode manette : place ce radial sur un emplacement de la barre manette. Cliquez, puis appuyez sur A, B, X, Y ou la croix directionnelle, seul ou avec LT, RT ou les deux maintenus."
L["An icon for each debuff type you can dispel. Middle of the Health Bar puts them two to a row."] = "Une icône par type de débuff que vous pouvez dissiper. Milieu de la barre de vie les place deux par ligne."
L["Inside, Centre"] = "Intérieur, centre"
L["Inside, Centre Left"] = "Intérieur, centre à gauche"
L["Inside, Centre Right"] = "Intérieur, centre à droite"
L["Middle of the Health Bar"] = "Milieu de la barre de vie"
L["The gap between the bars. 0 makes them touch."] = "L'espace entre les barres. 0 les colle."
L["The gap between the frames. In Raid Style it's between the bars: 0 makes them touch. Each style keeps its own."] = "L'espace entre les cadres. En style raid, il se mesure entre les barres : 0 les colle. Chaque style garde le sien."
L["The gap between the groups, measured between the bars."] = "L'espace entre les groupes, mesuré entre les barres."
